import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

public class Main {
    static void show(String step, ByteBuffer b) {
        System.out.printf("  %-22s pos=%d limit=%d cap=%d remaining=%d%n",
                step, b.position(), b.limit(), b.capacity(), b.remaining());
    }

    public static void main(String[] args) {
        ByteBuffer b = ByteBuffer.allocate(16);
        System.out.println("=== write mode ===");
        show("after allocate", b);
        b.put("hello".getBytes(StandardCharsets.US_ASCII));
        show("after put(5 bytes)", b);

        System.out.println("=== switch to read mode ===");
        b.flip();
        show("after flip()", b);
        System.out.println("  get() -> " + (char) b.get());
        System.out.println("  get() -> " + (char) b.get());
        show("after 2 gets", b);

        System.out.println("=== compact(): keep the unread tail, go back to write ===");
        b.compact();
        show("after compact()", b);
        System.out.println("  remaining unread bytes were moved to the front (llo -> now at 0..2)");

        System.out.println("=== clear(): reset cursors only, data stays ===");
        b.clear();
        show("after clear()", b);
        System.out.println("  hasArray=" + b.hasArray() + " (heap buffer), data is still there");
        System.out.println("  read the very first byte again -> " + (char) b.get(0));

        System.out.println("=== absolute get() does not move position ===");
        int posBefore = b.position();
        b.get(3);
        System.out.println("  position unchanged after get(3): " + (posBefore == b.position()));
    }
}
